Original (decoded):
```javascript
(function(){"use strict";Array.from(document.querySelectorAll("pre")).filter(function(r){return r.innerHTML.match(/<.*>/)||r.innerHTML.match(/\n/)}).forEach(function(r){return r.outerHTML="<code>"+r.outerHTML+"</code>"})...
```

Reformatted:
```javascript
// コードブロックを調整
// preタグとcodeタグの構造を調整し、表示を最適化するブックマークレット
// 🔧

(function() {
  "use strict";

  Array.from(document.querySelectorAll("pre"))
    .filter(function(element) {
      return element.innerHTML.match(/<.*>/) || element.innerHTML.match(/\n/);
    })
    .forEach(function(element) {
      element.outerHTML = "<code>" + element.outerHTML + "</code>";
    });
  // ...
})();
```

